import json,sys,os
from playwright.sync_api import sync_playwright
DEFS='''<defs><path id="keik-arc" d="M 18.48 68.2 A 36.4 36.4 0 1 1 81.52 68.2" fill="none"/><radialGradient id="keik-base" cx=".35" cy=".28" r=".9"><stop offset="0" stop-color="#fdf2ee"/><stop offset=".55" stop-color="#f3d9d1"/><stop offset="1" stop-color="#e1b6a9"/></radialGradient><linearGradient id="keik-raise" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fff"/><stop offset=".5" stop-color="#efd2c9"/><stop offset="1" stop-color="#b47a6a"/></linearGradient><linearGradient id="keik-sink" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#b47a6a"/><stop offset=".5" stop-color="#efd2c9"/><stop offset="1" stop-color="#fff"/></linearGradient><radialGradient id="keik-disc" cx=".4" cy=".32" r=".75"><stop offset="0" stop-color="#fffaf8"/><stop offset=".6" stop-color="#f8e8e3"/><stop offset="1" stop-color="#ecd0c7"/></radialGradient><linearGradient id="keik-gly" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#bb4835"/><stop offset="1" stop-color="#7c1f17"/></linearGradient><filter id="keik-bev" x="-20%" y="-20%" width="140%" height="140%" color-interpolation-filters="sRGB"><feGaussianBlur in="SourceAlpha" stdDeviation=".7" result="b"/><feSpecularLighting in="b" surfaceScale="3" specularConstant=".9" specularExponent="18" lighting-color="#fff" result="sp"><feDistantLight azimuth="225" elevation="42"/></feSpecularLighting><feComposite in="sp" in2="SourceAlpha" operator="in" result="spi"/><feOffset in="SourceAlpha" dx=".35" dy=".6" result="o"/><feGaussianBlur in="o" stdDeviation=".45" result="ob"/><feFlood flood-color="#3a0a06" flood-opacity=".4" result="fc"/><feComposite in="fc" in2="ob" operator="in" result="sh"/><feMerge><feMergeNode in="sh"/><feMergeNode in="SourceGraphic"/><feMergeNode in="spi"/></feMerge></filter></defs>'''
def p(d,a): return f'<path d="{d}" {a}/>' if d else ''
def badge(g,label,size,fs):
    tx=lambda fill,op,tr: f'<g transform="{tr}"><text style="font-family:Montserrat,system-ui,sans-serif;font-weight:700;font-size:{fs}px;letter-spacing:.08em;text-anchor:middle;fill:{fill};opacity:{op}"><textPath href="#keik-arc" startOffset="50%">{label}</textPath></text></g>'
    return (f'<svg viewBox="0 0 100 100" width="{size}" height="{size}"><circle cx="50" cy="50" r="48" fill="url(#keik-base)"/><circle cx="50" cy="50" r="46.6" fill="none" stroke="url(#keik-raise)" stroke-width="2.6"/><circle cx="50" cy="50" r="44.9" fill="none" stroke="url(#keik-sink)" stroke-width="1"/>'
      +tx('#fff','.95','translate(-.35 -.35)')+tx('#a86a5a','.55','translate(.4 .45)')+tx('#9b3426','1','translate(0 0)')
      +'<circle cx="42.2" cy="88" r="1.15" fill="url(#keik-raise)"/><circle cx="50" cy="89.6" r="1.4" fill="url(#keik-raise)"/><circle cx="57.8" cy="88" r="1.15" fill="url(#keik-raise)"/><circle cx="50" cy="50" r="32.4" fill="none" stroke="url(#keik-sink)" stroke-width="1.2"/><circle cx="50" cy="50" r="30.8" fill="url(#keik-disc)"/><circle cx="50" cy="50" r="30.8" fill="none" stroke="url(#keik-raise)" stroke-width="1.8"/>'
      +'<g transform="translate(30.8 30.8) scale(1.6)" filter="url(#keik-bev)">'
      +p(g.get('f'),'fill="url(#keik-gly)"')+p(g.get('s'),'fill="#6a1912"')+p(g.get('h'),'fill="rgba(255,255,255,.5)"')+p(g.get('c'),'fill="#f8e8e3"')
      +p(g.get('l'),'fill="none" stroke="#5a140e" stroke-width="1.1" stroke-linecap="round" stroke-linejoin="round"')
      +p(g.get('l2'),'fill="none" stroke="#f8e8e3" stroke-width=".8" stroke-linecap="round" stroke-linejoin="round"')+'</g></svg>')
items=json.loads(sys.argv[1]); out=sys.argv[2]
cols=''.join(f'<div class="c"><div class="t">{it["title"]}</div>{badge(it["g"],it["label"],300,it.get("fs",7.9))}<div class="sm">{badge(it["g"],it["label"],54,it.get("fs",7.9))}<span>skutečná velikost</span></div></div>' for it in items)
html=f'<!doctype html><html><head><meta charset="utf-8"><style>body{{margin:0;background:#fff;font-family:Montserrat,Arial,sans-serif;color:#7c1f17}}.w{{display:flex;gap:40px;padding:28px;justify-content:center}}.c{{display:flex;flex-direction:column;align-items:center;gap:14px}}.t{{font-weight:700;font-size:20px}}.sm{{display:flex;align-items:center;gap:10px;font-size:13px;color:#6e6c7a}}</style></head><body><svg width="0" height="0" style="position:absolute">{DEFS}</svg><div class="w">{cols}</div></body></html>'
with sync_playwright() as pw:
    b=pw.chromium.launch(); pg=b.new_page(viewport={'width':400*len(items)+60,'height':520},device_scale_factor=2)
    pg.set_content(html); pg.wait_for_timeout(300); pg.screenshot(path=out,full_page=True); b.close()
print(out)
